def rotar(lista, k):
    if not lista:
        return []

    n = len(lista)
    k %= n

    if k == 0:
        return lista[:]

    return lista[-k:] + lista[:-k]

def anagramas(a, b):
    a = a.lower().replace(" ", "")
    b = b.lower().replace(" ", "")
    return sorted(a) == sorted(b)

def balanceado(s):
    pila = []
    pares = {')': '(', ']': '[', '}': '{'}
    abiertos = set(pares.values())

    for c in s:
        if c in abiertos:
            pila.append(c)
        elif c in pares:
            if not pila or pila[-1] != pares[c]:
                return False
            pila.pop()

    return not pila
